DO $$ BEGIN RAISE EXCEPTION 'PROBE %', (SELECT string_agg(format('inv=%s txt=[%s] sup=%s posup=%s', i.supplier_invoice_number, i.po_text, i.supplier_id, (SELECT supplier_id FROM purchase_orders po WHERE po.po_number = regexp_replace(i.po_text, '\D', '', 'g') LIMIT 1)), ' ; ') FROM supplier_invoices i WHERE i.po_text IS NOT NULL AND public._sinv_po(i) IS NULL AND EXISTS (SELECT 1 FROM purchase_orders po WHERE po.po_number = regexp_replace(i.po_text, '\D', '', 'g') AND length(regexp_replace(i.po_text, '\D', '', 'g')) >= 6)); END $$;
